WITH b AS (SELECT x FROM TABLE(hcm.system.raw_query('default', 'project-task-index-v1', '{"size":0,"aggs":{"c":{"composite":{"size":65000,"sources":[{"code":{"terms":{"field":"Data.boundaryHierarchyCode.district"}}},{"mode":{"terms":{"field":"Data.deliveryMode"}}},{"tile":{"geotile_grid":{"field":"Data.geoPoint","precision":12}}}]},"aggs":{"c":{"geo_centroid":{"field":"Data.geoPoint"}},"kids":{"cardinality":{"field":"Data.individualId"}}}}},"query":{"bool":{"filter":[{"term":{"Data.administrationStatus":"ADMINISTRATION_SUCCESS"}},{"term":{"Data.zeroDose":true}}]}}}')) CROSS JOIN UNNEST(CAST(json_extract(result, '$.aggregations.c.buckets') AS array(json))) AS t(x))
SELECT d.region, d.district, d.boundary_code, CASE json_extract_scalar(x, '$.key.mode') WHEN 'FIXED_POST' THEN 'Fixed post' WHEN 'HOUSE_TO_HOUSE' THEN 'House to house' WHEN 'TRANSIT_POST' THEN 'Transit post' ELSE json_extract_scalar(x, '$.key.mode') END AS delivery_mode,
       CAST(json_extract_scalar(x, '$.c.location.lat') AS double) AS latitude, CAST(json_extract_scalar(x, '$.c.location.lon') AS double) AS longitude, CAST(json_extract_scalar(x, '$.kids.value') AS bigint) AS zd_children
FROM b JOIN microplan.public.dim_district d ON d.boundary_code = json_extract_scalar(x, '$.key.code')
